import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    req.role = payload.role;
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  next();
}

// Search endpoint with flexible filtering
app.get('/api/v2/reports/search', extractTenant, async (req, res) => {
  const { category, date_from, date_to, sort_by, order } = req.query;

  // Build base query with tenant isolation
  let query = `SELECT r.id, r.title, r.category, r.created_at, r.author_id, 
               r.content, r.internal_notes, r.financial_data
               FROM reports r WHERE r.tenant_id = $1`;
  const params = [req.tenantId];
  let paramIdx = 2;

  if (category) {
    query += ` AND r.category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  if (date_from) {
    query += ` AND r.created_at >= $${paramIdx}`;
    params.push(date_from);
    paramIdx++;
  }

  if (date_to) {
    query += ` AND r.created_at <= $${paramIdx}`;
    params.push(date_to);
    paramIdx++;
  }

  // Sort - developer assumed sort_by would be from a dropdown
  const allowedOrder = ['ASC', 'DESC'];
  const sanitizedOrder = allowedOrder.includes(order?.toUpperCase()) ? order.toUpperCase() : 'DESC';

  if (sort_by) {
    query += ` ORDER BY ${sort_by} ${sanitizedOrder}`;
  } else {
    query += ` ORDER BY r.created_at DESC`;
  }

  query += ` LIMIT 100`;

  try {
    const result = await pool.query(query, params);
    res.json({ reports: result.rows });
  } catch (e) {
    console.error('Query error:', e.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Export endpoint - generates CSV
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  const { report_ids } = req.body;
  if (!Array.isArray(report_ids) || report_ids.length === 0) {
    return res.status(400).json({ error: 'report_ids required' });
  }

  const placeholders = report_ids.map((_, i) => `$${i + 2}`).join(',');
  const query = `SELECT * FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;

  try {
    const result = await pool.query(query, [req.tenantId, ...report_ids]);
    const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
    res.setHeader('Content-Type', 'text/csv');
    res.send(csv);
  } catch (e) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Admin endpoint - update report visibility
app.put('/api/v2/reports/:id/visibility', extractTenant, async (req, res) => {
  if (req.role !== 'admin') {
    return res.status(403).json({ error: 'Admin only' });
  }
  const { visibility } = req.body;
  const query = `UPDATE reports SET visibility = $1 WHERE id = $2 AND tenant_id = $3`;
  try {
    await pool.query(query, [visibility, req.params.id, req.tenantId]);
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: 'Update failed' });
  }
});

app.listen(3000, () => console.log('Report service running on :3000'));
